#include <stdio.h>

#define N 100010
int h[N], ph[N], hp[N];
int sz = 0, idx = 0;

void swap_int(int *a, int *b) {
    int t = *a; *a = *b; *b = t;
}

void heap_swap(int a, int b) {
    swap_int(&h[a], &h[b]);
    swap_int(&hp[a], &hp[b]);
    ph[hp[a]] = a;
    ph[hp[b]] = b;
}

void down(int u) {
    int t = u;
    if (u * 2 <= sz && h[u * 2] < h[t]) t = u * 2;
    if (u * 2 + 1 <= sz && h[u * 2 + 1] < h[t]) t = u * 2 + 1;
    if (t != u) {
        heap_swap(u, t);
        down(t);
    }
}

void up(int u) {
    while (u / 2 && h[u / 2] > h[u]) {
        heap_swap(u / 2, u);
        u /= 2;
    }
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    while (n--) {
        char op[3];
        scanf("%s", op);
        if (op[0] == 'I') {
            int x;
            scanf("%d", &x);
            ++sz;
            ++idx;
            ph[idx] = sz;
            hp[sz] = idx;
            h[sz] = x;
            up(sz);
        } else if (op[0] == 'P') {
            printf("%d%c", h[1], 10);
        } else if (op[0] == 'D' && op[1] == 'M') {
            heap_swap(1, sz);
            --sz;
            down(1);
        } else if (op[0] == 'D') {
            int k;
            scanf("%d", &k);
            int p = ph[k];
            heap_swap(p, sz);
            --sz;
            up(p);
            down(p);
        } else if (op[0] == 'C') {
            int k, x;
            scanf("%d%d", &k, &x);
            int p = ph[k];
            h[p] = x;
            up(p);
            down(p);
        }
    }
    return 0;
}
